def find_witnesses(extend_set: list[list[int]]) -> dict[frozenset, list[int]]:
    """
    Finds a die for every subset of `extend_set` beating exactly that subset (and not beating all dice outside of the subset).
    This means that `extend_set` must have the very special property that such a die exists for every subset.
    """
    n = len(extend_set)
    k = len(extend_set[0])
    slot_vals = [s + 0.5 for s in range(n + 1)]
    mapping = {}
    for witness_die in tqdm(itertools.product(slot_vals, repeat=k), total=len(slot_vals)**k):
        s = frozenset({ i for i in range(n) if beats(witness_die, extend_set[i]) })  # type: ignore
        if s not in mapping:
            mapping[s] = witness_die
    assert len(mapping) == 2**n
    return mapping


def extend_step(dice: DiceSet, tournament: list[list[int]], extend_set: list[list[int]], witnesses: dict[frozenset, list[int]]) -> DiceSet:
    """
    Extends a set of `n` dice to a new tournament. The tournament formed by the dice should
    be exactly the subtournament of `tournament` using the first `n` vertices.
    Then, using a more general version of the extension construction given by Bednay and Bozoki,
    the set can be extended by `m` dice using `2r` new faces. Here `m` is the number of dice in `extend_set`
    and `r` is the number of faces needed to realize the extension set.
    `witnesses` here is the mapping from a subset of the extension set to the die that beats exactly that subset.
    """
    
    # I figured it out, but the default is only weakly nontransitive
    # So I had to change it to avoid draws
    # I also added a more general approach to be able to use any extend set

    m = len(extend_set)
    r = len(extend_set[0])
    n = dice.n
    d = dice.faces
    k = d // 2

    assert n + m == len(tournament), f"{n=}, {m=}, {len(tournament)=}"
    dice_blocks = dice.as_blocks()

    # just a very large M to make it work
    M = 8*max(max(dice_blocks)) + 1

    def multiply(a, s): return [s*v for v in a]

    sub_t = [t[-m:] for t in tournament[-m:]]
    sub_faces = construct_tournament(sub_t)

    new_dice = []
    all_block_counts = [defaultdict(int) for _ in range(r)]
    for i in range(n):
        target_subset = frozenset(j for j in range(m) if tournament[i][n + j])
        for j, b in enumerate(witnesses[target_subset]):
            all_block_counts[j][b] += 1

    max_occ = max(max(x.values()) for x in all_block_counts)
    max_occ *= 2

    lane_counts = [defaultdict(int) for _ in range(r)]
    for i in range(n):
        target_subset = frozenset(j for j in range(m) if tournament[i][n + j])
        B = witnesses[target_subset]
        B = multiply(B, max_occ)
        for j, b in enumerate(B):
            lane_counts[j][b] += 1
        B = [x + lane_counts[j][x] - 1 for j, x in enumerate(B)]
        M = max(M, max(B))
        blocks = dice_blocks[i] + B + [-b for b in B]
        new_dice.append(blocks)

    for i, (A_i, C_i) in enumerate(zip(extend_set, sub_faces.dice)):
        A_i = multiply(A_i, max_occ)
        a = (m + r)//2
        C_minus_M = [v - M for v in C_i[:a]]
        C_plus_M = [v + M for v in C_i[a:]]
        neg_A = [M - v for v in A_i]
        
        D = [M + i] * (k - m//2)
        blocks = [-x for x in D] + D + C_minus_M + C_plus_M + A_i + neg_A
        new_dice.append(blocks)

    return DiceSet.from_blocks(new_dice, 10_000_000).minimize()


def create_tournament(tournament: list[list[int]], seed: DiceSet, extend_set: list[list[int]], show_progress: bool = False):
    step = len(extend_set)
    n = len(tournament)
    assert (n - seed.n) % step == 0
    witnesses = find_witnesses(extend_set)
    dice = seed

    r = range(seed.n + step, n + 1, step)
    if show_progress:
        r = tqdm(r)
    for i in r:
        sub_t = [t[:i] for t in tournament[:i]]
        dice = extend_step(dice, sub_t, extend_set, witnesses)
    return dice


